# Sync backend/.env from contracts deployment manifest (generated by DeployAllDemo).
param(
    [string]$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path,
    [string]$DeploymentFile = "",
    [string]$RpcUrl = "",
    [string]$AnvilPrivateKey = "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80"
)

$ErrorActionPreference = "Stop"

if (-not $DeploymentFile) {
    $DeploymentFile = Join-Path $RepoRoot "contracts\deployments\anvil-31337-demo.json"
}

if (-not (Test-Path $DeploymentFile)) {
    throw "Deployment manifest not found: $DeploymentFile`nRun DeployAllDemo first."
}

$deployment = Get-Content $DeploymentFile -Raw | ConvertFrom-Json

$required = @("registry", "vaultExecution", "swapRouter", "scenarioDeployer")
foreach ($key in $required) {
    if (-not $deployment.$key) {
        throw "Deployment manifest missing '$key' in $DeploymentFile"
    }
}

$envPath = Join-Path $RepoRoot "backend\.env"
$deploymentPathRel = "..\contracts\deployments\" + (Split-Path $DeploymentFile -Leaf)

if (-not $RpcUrl) {
    if ($deployment.network -eq "monad-testnet") {
        $RpcUrl = if ($env:MONAD_RPC_URL) { $env:MONAD_RPC_URL } else { "https://testnet-rpc.monad.xyz" }
    } else {
        $RpcUrl = "http://127.0.0.1:8545"
    }
}

$lines = @(
    "# Auto-generated by scripts/sync-backend-env.ps1 — $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')",
    "CHAIN_MODE=demo",
    "RPC_URL=$RpcUrl",
    "PORT=8080",
    "",
    "DEMO_DEPLOYMENT_PATH=$deploymentPathRel",
    "DEMO_REGISTRY_ADDRESS=$($deployment.registry)",
    "VAULT_EXECUTION_ADDRESS=$($deployment.vaultExecution)",
    "DEMO_SWAP_ROUTER_ADDRESS=$($deployment.swapRouter)",
    "DEMO_SCENARIO_DEPLOYER=$($deployment.scenarioDeployer)",
    "",
    "# Anvil account #0 (deployer + agentSigner by default)",
    "SWAP_PRIVATE_KEY=$AnvilPrivateKey",
    "EXECUTOR_PRIVATE_KEY=$AnvilPrivateKey",
    "AGENT_PRIVATE_KEY=$AnvilPrivateKey",
    ""
)

Set-Content -Path $envPath -Value ($lines -join "`n") -Encoding ASCII

Write-Host "Wrote backend/.env from deployment manifest:"
Write-Host "  registry       = $($deployment.registry)"
Write-Host "  vault          = $($deployment.vaultExecution)"
Write-Host "  swapRouter     = $($deployment.swapRouter)"
Write-Host "  scenarioDeployer = $($deployment.scenarioDeployer)"

return @{
    EnvPath = $envPath
    Deployment = $deployment
}
